#include <iostream>
#include <unordered_map>
using namespace std;

int main() {
    unordered_map<string, int> scores;

    // insert
    scores["Alice"] = 95;
    scores["Bob"] = 82;
    scores["Carol"] = 78;

    // lookup
    cout << scores["Alice"] << endl;   // 95

    // check if key exists
    cout << (scores.find("Bob") != scores.end()) << endl;   // 1 (true)
    cout << (scores.find("Dave") != scores.end()) << endl;  // 0 (false)

    // delete
    scores.erase("Bob");

    // loop over all pairs
    for (auto &pair : scores) {
        cout << pair.first << ": " << pair.second << endl;
    }

    return 0;
}

